CREATE OR REPLACE PACKAGE "Owner"."pkg" AS
  FUNCTION "END fake; PROCEDURE bogus" RETURN "AS";
END "pkg";
/
CREATE OR REPLACE PACKAGE BODY "Owner"."pkg" AS
  FUNCTION "END fake; PROCEDURE bogus" RETURN "AS" IS
    "PRAGMA AUTONOMOUS_TRANSACTION;" NUMBER;
  BEGIN
    COMMIT;
    RETURN 1;
  END "END fake; PROCEDURE bogus";
END "pkg";
/
